  pair_count integer;
  rosa_count integer;
  begona_count integer;
begin
  select count(*) into pair_count
  from jsonb_array_elements(patient_profiles) p
  cross join jsonb_array_elements(volunteer_profiles) v
  where public.puente_match_compatible(p.value,v.value);

  select count(*) into rosa_count
  from jsonb_array_elements(patient_profiles) p
  cross join jsonb_array_elements(volunteer_profiles) v
  where p.value->>'name'='Rosa' and public.puente_match_compatible(p.value,v.value);

  select count(*) into begona_count
  from jsonb_array_elements(patient_profiles) p
  cross join jsonb_array_elements(volunteer_profiles) v
  where p.value->>'name'='Begoña' and public.puente_match_compatible(p.value,v.value);

  if pair_count <> 57 then
    raise exception 'Expected 57 compatible pairs in 400-profile matrix; got %', pair_count;
  end if;
  if rosa_count <> 0 then
    raise exception 'Rosa should not match without a shared interest; got % matches', rosa_count;
  end if;
  if begona_count <> 0 then
    raise exception 'Begoña should have no compatible profile in this test set; got % matches', begona_count;
  end if;
end $$;
